  // ---- emi-provenance.js
  factories["emi-provenance"] = function (exports, module, require) {
"use strict";
// M8: provenance, where every beat of a composed piece came from, in words
// (for the piano roll's hover view) and as a record (written next to an
// exported .mid, so a piece can be traced and, later, rated beat by beat).
//
// Bars and beats are counted as in printed scores: a chorale's pickup is bar
// 0, its first full bar bar 1.

const signatures = require("emi-signatures");
const quality = require("emi-quality");

const VOICES = ["soprano", "alto", "tenor", "bass"];

const beatsPerBar = (db) => Math.round((db.meter[0] * 4) / db.meter[1]);

// Where grouping g sits in its chorale: { bar, beat }.
function placeOf(db, g) {
  const work = db.works.find((w) => w.id === g.work);
  const bpb = beatsPerBar(db);
  return { bar: Math.floor(g.index / bpb) + (work && work.pickup ? 0 : 1), beat: (g.index % bpb) + 1 };
}

// One provenance entry in words, e.g.
// "bwv260, bar 4 beat 2 · P · octaves moved · signature soprano 3-2-1".
function describeBeat(db, entry, groupings = new Map(db.groupings.map((g) => [g.id, g]))) {
  const g = groupings.get(entry.grouping);
  if (!g) return entry.work;
  const { bar, beat } = placeOf(db, g);
  const parts = [`${g.work}, bar ${bar} beat ${beat}`];
  if (g.speac) parts.push(g.speac.beat);
  if (entry.shift && entry.shift.some((v) => v !== 0)) {
    const moved = entry.shift.map((v, i) => (v ? `${VOICES[i]} ${v > 0 ? "up" : "down"} ${Math.abs(v / 12)} oct.` : null)).filter(Boolean);
    parts.push(moved.join(", "));
  }
  if (entry.block) parts.push("signature block");
  if (entry.signatures && entry.signatures.length) parts.push(nameOf(db, entry.signatures[0]));
  return parts.join(" · ");
}

function nameOf(db, id) {
  const found = (db.signatures || []).find((s) => s.id === id);
  return found ? signatures.describe(found, db.mode) : id;
}

// The record of a composed piece, as written next to its .mid:
//   { piece, source, seed, key, meter, ppq, form, settings, corpus,
//     quotes, parallels, beats: [{ tick, grouping, work, bar, beat, speac,
//     level, shift?, block?, signatures? }] }
function record(db, piece, settings = {}) {
  const groupings = new Map(db.groupings.map((g) => [g.id, g]));
  const q = quality.quotes(db, piece);
  const found = quality.parallels(piece, { db });
  return {
    piece: piece.id,
    source: piece.source,
    seed: piece.seed,
    key: piece.key,
    meter: piece.meter,
    ppq: piece.ppq,
    form: piece.form,
    settings,
    corpus: { works: db.works.length, mode: db.mode, version: db.version, signatures: (db.signatures || []).length },
    quotes: {
      melody: { notes: q.melody.notes, voice: VOICES[q.melody.voice - 1] || null, work: q.melody.work },
      run: { beats: q.run.beats, work: q.run.work },
      limits: quality.LIMITS,
    },
    parallels: found.map((p) => ({ tick: p.tick, from: p.from, voices: p.voices.map((v) => VOICES[v - 1]), interval: p.interval, new: !p.inherited })),
    beats: (piece.provenance || []).map((entry) => {
      const g = groupings.get(entry.grouping);
      const out = { tick: entry.tick, grouping: entry.grouping, work: entry.work };
      if (g) Object.assign(out, placeOf(db, g), { speac: g.speac ? g.speac.beat : null });
      out.level = entry.level || 0;
      if (entry.shift) out.shift = entry.shift;
      if (entry.block) out.block = entry.block;
      if (entry.signatures) out.signatures = entry.signatures.map((id) => nameOf(db, id));
      return out;
    }),
  };
}

exports.placeOf = placeOf;
exports.describeBeat = describeBeat;
exports.record = record;
  };

  // ---- emi-abtest.js
  factories["emi-abtest"] = function (exports, module, require) {
"use strict";
// M8: a blind A/B listening test. Each pair is one of Bach's chorales and a
// piece composed in that chorale's form (the same phrases, cadences and
// length), both in the chorale's own key; Bach is A in half the pairs. A
// listener hears both and says which is Bach; if listeners can't pick Bach
// out more often than guessing would, the recombination passes (PLAN.md, M8).
//
//   test = build(db, { count, seed, signatures, exclude })   exclude: chorales to leave out
//     { id, tempo, pairs: [{ key, bars, beatsPerBar, A, B }], answers: [...] }
//   A and B: notes [onset, pitch, duration, voice], onset and duration in beats.
//   answers (one per pair): { bach: "A" | "B", chorale, title, piece, template }
// page(test) (emi-abtest-page) turns it into a self-contained web page.

const rng = require("emi-rng");
const forms = require("emi-form");
const quality = require("emi-quality");

const NAMES = ["C", "C#", "D", "Eb", "E", "F", "F#", "G", "Ab", "A", "Bb", "B"];

function build(db, { count = 10, seed = 1, signatures = true, tempo = 84, exclude = [] } = {}) {
  const random = rng.create(seed);
  const order = db.templates.map((t) => t.work).filter((w) => !exclude.includes(w));
  for (let i = order.length - 1; i > 0; i--) {
    const j = random.int(i + 1);
    [order[i], order[j]] = [order[j], order[i]];
  }
  // Bach is A in half the pairs and B in the other half, in shuffled order,
  // so no run of one side gives anything away.
  const sides = Array.from({ length: count }, (_, i) => i % 2 === 0);
  for (let i = sides.length - 1; i > 0; i--) {
    const j = random.int(i + 1);
    [sides[i], sides[j]] = [sides[j], sides[i]];
  }
  const sources = quality.corpusLines(db).events;
  const beatsPerBar = Math.round((db.meter[0] * 4) / db.meter[1]);
  const pairs = [];
  const answers = [];
  for (const work of order) {
    if (pairs.length >= count) break;
    const result = forms.compose(db, { seed: seed * 1000 + pairs.length + 1, template: work, signatures });
    if (!result.ok || result.piece.form.overLimit) continue; // this form can't be filled cleanly: another chorale
    const info = db.works.find((w) => w.id === work);
    // Back to the chorale's own key: both move by what normalizing moved it.
    const shift = -(info.transposedBy || 0);
    const chorale = asBeats(sources.get(work), db.beatTicks, shift);
    const piece = asBeats(result.piece.events, db.beatTicks, shift);
    const tonic = (((result.piece.key.tonic + shift) % 12) + 12) % 12;
    const bachFirst = sides[pairs.length];
    pairs.push({
      key: `${NAMES[tonic]} ${result.piece.key.mode}`,
      bars: Math.ceil(Math.max(end(chorale), end(piece)) / beatsPerBar),
      beatsPerBar,
      A: bachFirst ? chorale : piece,
      B: bachFirst ? piece : chorale,
    });
    answers.push({ bach: bachFirst ? "A" : "B", chorale: work, title: info.title || null, piece: result.piece.id, template: work, signatures });
  }
  // The id names this test's music, so a browser keeps choices per test.
  let hash = 0x811c9dc5;
  for (const ch of JSON.stringify(pairs)) hash = Math.imul(hash ^ ch.charCodeAt(0), 16777619) >>> 0;
  return { id: `abtest-${seed}-${hash.toString(36)}`, tempo, pairs, answers };
}

// Notes [on, pitch, dur, voice] in ticks, as [onset, pitch, duration, voice]
// in beats from the first note, moved by `shift` semitones.
function asBeats(events, beatTicks, shift) {
  const first = Math.min(...events.map((e) => e[0]));
  const round = (x) => Math.round(x * 1000) / 1000;
  return events
    .map(([on, pitch, dur, voice]) => [round((on - first) / beatTicks), pitch + shift, round(dur / beatTicks), voice])
    .sort((a, b) => a[0] - b[0] || a[3] - b[3]);
}

const end = (notes) => Math.max(...notes.map((n) => n[0] + n[2]));

// The answers, lightly hidden in the page (so a glance at the page source
// doesn't give them away): the JSON's character codes XORed with a key.
function seal(answers, key = 0x5a) {
  return Array.from(JSON.stringify(answers)).map((c) => c.charCodeAt(0) ^ key);
}

function unseal(codes, key = 0x5a) {
  return JSON.parse(codes.map((c) => String.fromCharCode(c ^ key)).join(""));
}

// One-sided binomial test: the chance of k or more right out of n by
// guessing (p = 0.5 each).
function chance(k, n) {
  let total = 0;
  let ways = 1; // n choose j
  for (let j = 0; j <= n; j++) {
    if (j >= k) total += ways;
    ways = (ways * (n - j)) / (j + 1);
  }
  return total / 2 ** n;
}

exports.build = build;
exports.seal = seal;
exports.unseal = unseal;
exports.chance = chance;
  };

